    id: 'operacao-paperclip',
    name: 'Operação Paperclip (A Transferência do Conhecimento Nazista)',
    aliases: ['Operação Paperclip', 'Operation Paperclip', 'Paperclip', 'cientistas nazistas nos EUA', 'Werner von Braun', 'NASA e o Nazismo'],
    cat: 'ordem',
